// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }
    function testRegression_property() public {
        address nonAdmin = address(0x1234);
        vm.deal(nonAdmin, 1 ether);


        vm.prank(nonAdmin);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("updateLRTConfig(address)", address(0xdead)));

        assertTrue(ok == false, "updateLRTConfig should revert for non-admin");
    }
}
